export const copy = {
  sw: { ...translations.sw, ...sw },
  en: { ...translations.en, ...en },
};
export function localizeError(error: unknown, language: Language) {
  const m = String(error);
  const t = copy[language];
  if (/Maps search/i.test(m)) return t.searchUnavailable;
  if (/Maps routing|Route geometry|Route unavailable|GOOGLE_MAPS_KEY/i.test(m))
    return t.mapsUnavailable;
  if (/Location permission/i.test(m)) return t.locationRequired;
  if (/Invalid or expired|verification code/i.test(m)) return t.invalidCode;
  if (/phone.*registered|duplicate.*phone|unique.*users_phone/i.test(m))
    return t.phoneTaken;
  if (/Too many/i.test(m)) return t.tooMany;
  if (/Session expired|verify your phone/i.test(m)) return t.sessionExpired;
  if (/outside service/i.test(m)) return t.outsideArea;
  if (/within 150/i.test(m)) return t.mustArrive;
  if (/Approved driver|approval required|subscription required/i.test(m))
    return t.approvalRequired;
  if (/Offer unavailable/i.test(m)) return t.noOffer;
  if (/support review|Invalid transition|trip exception/i.test(m))
    return t.supportReview;
  if (/Vehicle colour required/i.test(m)) return t.vehicleColor;
  if (/Licence expired/i.test(m)) return t.licenceExpired;
  if (/unavailable|integration|Routing|Places/i.test(m)) return t.unavailable;
  if (/network|fetch|timeout/i.test(m)) return t.networkError;
  return Object.values(t).includes(m.replace(/^Error: /, ''))
    ? m.replace(/^Error: /, '')
    : t.genericError;
}
export const rideStatus = (status: string, language: Language) =>
  ({
    requested: copy[language].searching,
    accepted: copy[language].accepted,
    arrived: copy[language].arrivedStatus,
    in_progress: copy[language].inProgress,
    completed: copy[language].completed,
    cancelled: copy[language].cancelled,
  })[status] || copy[language].details;
